export function renderNote(note) {
  var html = '';
  html = html + '<article class="note">';
  html = html + '<h3>' + escapeNote(note.author) + '</h3>';
  if (note.day) {
    html = html + '<time>' + escapeNote(note.day) + '</time>';
  }
  html = html + '<p>' + escapeNote(note.text) + '</p>';
  html = html + '</article>';
  return html;
}

