import assert from 'node:assert/strict';
import { test } from 'node:test';

import { renderNote } from '../src/notes/render.js';

test('escapes HTML in author, day and text', () => {
  const html = renderNote({ author: '<b>Al</b>', day: '"today"', text: '<script>x</script>' });
  assert.equal(
    html,
    '<article class="note"><h3>&lt;b&gt;Al&lt;/b&gt;</h3><time>&quot;today&quot;</time><p>&lt;script&gt;x&lt;/script&gt;</p></article>'
  );
});

test('omits the time element when there is no day', () => {
  const html = renderNote({ author: 'Al', text: 'hi' });
  assert.equal(html, '<article class="note"><h3>Al</h3><p>hi</p></article>');
});
